init = (0,) * nkeep
seen = {init: 0}
order = [init]
trans = []
if nkeep:
    index = 0
    grow = order.append
    while index < len(order):
        current = order[index]
        index += 1
        here = [rowtabs[j][current[j]] for j in range(nkeep)]
        out = []
        append = out.append
        for column in zip(*here):
            try:
                append(seen[column])
            except KeyError:
                if len(order) >= TUPLE_CAP:
                    raise ComplexityError()
                pid = len(order)
                append(pid)
                seen[column] = pid
                grow(column)
        trans.append(out)
else:
    trans.append([0] * nrep)
